#!/usr/bin/env python3
"""生成《数治理方 · 六端生态》正式文档 (.docx)"""
from docx import Document
from docx.shared import Pt, Cm, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import nsdecls
from docx.oxml import parse_xml

doc = Document()

for sec in doc.sections:
    sec.top_margin = Cm(2.5); sec.bottom_margin = Cm(2.5)
    sec.left_margin = Cm(2.5); sec.right_margin = Cm(2.5)

style = doc.styles['Normal']
style.font.name = '\u5b8b\u4f53'; style.font.size = Pt(11)
style.paragraph_format.line_spacing = 1.5
style.font.color.rgb = RGBColor(0x33,0x33,0x33)
rPr = style.element.get_or_add_rPr()
rPr.append(parse_xml(f'<w:rFonts {nsdecls("w")} w:eastAsia="\u5b8b\u4f53"/>'))

BL = RGBColor(0x1F,0x38,0x64); BA = RGBColor(0x25,0x63,0xEB)
WH = RGBColor(0xFF,0xFF,0xFF); BK = RGBColor(0x33,0x33,0x33)
GR = RGBColor(0x64,0x74,0x8B); GD = RGBColor(0x55,0x55,0x55)

def rf(run, cn, sz, b=False, c=None):
    run.font.size=Pt(sz); run.font.bold=b; run.font.name=cn
    rP=run._element.get_or_add_rPr()
    rP.append(parse_xml(f'<w:rFonts {nsdecls("w")} w:eastAsia="{cn}"/>'))
    if c: run.font.color.rgb=c

def T(text, lv=0):
    p=doc.add_paragraph(); r=p.add_run(text)
    sizes={0:(22,True,BL),1:(16,True,BL),2:(13,True,BA),3:(11,True,BK)}
    sz,b,c=sizes.get(lv,(11,False,BK)); rf(r,'\u9ed1\u4f53',sz,b,c)
    if lv==0: p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_after=Pt(4)
    elif lv==1: p.paragraph_format.space_before=Pt(24); p.paragraph_format.space_after=Pt(8)
    elif lv==2: p.paragraph_format.space_before=Pt(16); p.paragraph_format.space_after=Pt(6)
    elif lv==3: p.paragraph_format.space_before=Pt(10); p.paragraph_format.space_after=Pt(4)

def B(text,ind=False):
    p=doc.add_paragraph(); r=p.add_run(text); rf(r,'\u5b8b\u4f53',11)
    if ind: p.paragraph_format.first_line_indent=Cm(0.7)
    p.paragraph_format.space_after=Pt(4)

def BLT(text):
    p=doc.add_paragraph(); r=p.add_run('\u2022 '+text); rf(r,'\u5b8b\u4f53',10.5)
    p.paragraph_format.left_indent=Cm(0.8); p.paragraph_format.space_after=Pt(2)

def CBG(cell,hx):
    cell._tc.get_or_add_tcPr().append(parse_xml(f'<w:shd {nsdecls("w")} w:fill="{hx}"/>'))

def TB(headers,rows,ws=None):
    t=doc.add_table(rows=1+len(rows),cols=len(headers))
    t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.CENTER
    for i,h in enumerate(headers):
        cl=t.rows[0].cells[i]; cl.text=''; p=cl.paragraphs[0]; r=p.add_run(h)
        rf(r,'\u9ed1\u4f53',10,True,WH); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; CBG(cl,'1F3864')
    for ri,rd in enumerate(rows):
        for ci,v in enumerate(rd):
            cl=t.rows[ri+1].cells[ci]; cl.text=''; p=cl.paragraphs[0]; r=p.add_run(str(v))
            rf(r,'\u5b8b\u4f53',9.5)
            if ri%2==1: CBG(cl,'F0F4F8')
    if ws:
        for i,w in enumerate(ws):
            for row in t.rows: row.cells[i].width=Cm(w)
    doc.add_paragraph(); return t

def LL(label,text,c=None):
    p=doc.add_paragraph(); r=p.add_run(label+'  '); rf(r,'\u5b8b\u4f53',11,True,c or BL)
    r2=p.add_run(text); rf(r2,'\u5b8b\u4f53',11); p.paragraph_format.space_after=Pt(2)

def ECO(title,role,ins,outs,scenes):
    """生态链路块：端口名+生态位+输入列表+输出列表+场景标签"""
    p=doc.add_paragraph(); r1=p.add_run(title+' \u00b7 '); rf(r1,'\u9ed1\u4f53',15,True,BA)
    r2=p.add_run(role); rf(r2,'\u5b8b\u4f53',12,c=GR); p.paragraph_format.space_after=Pt(2)

    p=doc.add_paragraph(); r=p.add_run('\u25a0 \u751f\u6001\u94fe\u8def'); rf(r,'\u5b8b\u4f53',10,True,GR)
    p.paragraph_format.space_before=Pt(8); p.paragraph_format.space_after=Pt(4)

    pp=doc.add_paragraph(); r=pp.add_run('\u2190 \u4ece\u54ea\u63a5\u6570\u636e\uff1a'); rf(r,'\u5b8b\u4f53',10,True,RGBColor(0x34,0xd3,0x99))
    r2=pp.add_run('  '+'\uff5c'.join(ins)); rf(r2,'\u5b8b\u4f53',10,c=GR)
    pp.paragraph_format.left_indent=Cm(0.6); pp.paragraph_format.space_after=Pt(2)

    pp=doc.add_paragraph(); r=pp.add_run('\u2192 \u5f80\u54ea\u9001\u6570\u636e\uff1a'); rf(r,'\u5b8b\u4f53',10,True,RGBColor(0xf5,0x9e,0x0b))
    r2=pp.add_run('  '+'\uff5c'.join(outs)); rf(r2,'\u5b8b\u4f53',10,c=GR)
    pp.paragraph_format.left_indent=Cm(0.6); pp.paragraph_format.space_after=Pt(2)

    if scenes:
        pp=doc.add_paragraph(); r=pp.add_run('\u573a\u666f\uff1a'); rf(r,'\u5b8b\u4f53',10,True,GR)
        r2=pp.add_run('  '+'\u3000'.join(scenes)); rf(r2,'\u5b8b\u4f53',9,c=GD)
        pp.paragraph_format.left_indent=Cm(0.6); pp.paragraph_format.space_after=Pt(8)

def DEF(title,text):
    p=doc.add_paragraph(); r=p.add_run(title); rf(r,'\u5b8b\u4f53',10.5,True,RGBColor(0x81,0x88,0xcf))
    p.paragraph_format.space_after=Pt(2)
    B(text,True)

def BRK(title,text):
    p=doc.add_paragraph(); r=p.add_run(title); rf(r,'\u5b8b\u4f53',10.5,True,RGBColor(0xf8,0x71,0x71))
    p.paragraph_format.space_before=Pt(8); p.paragraph_format.space_after=Pt(2)
    pp=doc.add_paragraph(); r=pp.add_run(text); rf(r,'\u5b8b\u4f53',10.5,c=RGBColor(0xfc,0xa5,0xa5))
    pp.paragraph_format.left_indent=Cm(0.6); pp.paragraph_format.space_after=Pt(4)

def NET(icon,title,text):
    p=doc.add_paragraph(); r=p.add_run(f'{icon}  {title}'); rf(r,'\u9ed1\u4f53',12,True,BL)
    p.paragraph_format.space_after=Pt(2)
    B(text,True)

